INSERT INTO items (id, owner_id, title, description, price_kopeks, status, attributes, created_at, updated_at) VALUES
    ('a0000000-0000-4000-a000-000000000001', 'd0000000-0000-4000-a000-000000000001', 'iPhone 13 128GB, идеальное состояние',
     'Продаю iPhone 13 на 128 ГБ в отличном состоянии. Куплен официально в феврале, всегда в чехле и со стеклом, царапин нет. Батарея держит 91%, менялась только защитная плёнка. В комплекте оригинальная коробка, кабель USB-C и чек. Работает без нареканий, Face ID и все камеры исправны. Отдаю, потому что перешёл на другую модель. Возможна проверка при встрече в любом торговом центре, помогаю с доставкой по городу.',
     4990000, 'published', '{"category":"electronics","condition":"used"}', now() - interval '18 days', now() - interval '18 days'),
    ('a0000000-0000-4000-a000-000000000002', 'd0000000-0000-4000-a000-000000000002', 'Велосипед горный Merida Big Nine',
     'Горный велосипед Merida Big Nine, рама 19 дюймов, колёса 29. Куплен два сезона назад, катался по выходным в парке и на легком грунте. Полностью обслужен: смазана цепь, отрегулированы тормоза, переключатели работают чётко на всех передачах. Резина с хорошим протектором, восьмёрок нет. В подарок отдам насос и держатель для фляги. Идеален для города и несложных маршрутов, реальному покупателю уступлю.',
     3450000, 'published', '{"category":"sport","condition":"used"}', now() - interval '15 days', now() - interval '15 days'),
    ('a0000000-0000-4000-a000-000000000003', 'd0000000-0000-4000-a000-000000000003', 'Диван-кровать, раскладной, серый',
     'Раскладной диван-кровать в спокойном сером цвете, механизм еврокнижка. Спальное место 200 на 140, раскладывается одним движением, внутри вместительный ящик для белья. Обивка рогожка, устойчива к затяжкам, следов от животных нет — питомцев в доме не было. Каркас деревянный, ничего не скрипит. Продаём в связи с переездом, самовывоз или помогу организовать грузовое такси. Отдам вместе с двумя декоративными подушками.',
     1890000, 'published', '{"category":"furniture","condition":"used"}', now() - interval '12 days', now() - interval '12 days'),
    ('a0000000-0000-4000-a000-000000000004', 'd0000000-0000-4000-a000-000000000004', 'Детская коляска 2 в 1 Anex',
     'Коляска Anex 2 в 1: люлька и прогулочный блок в одном комплекте. Пользовались одним ребёнком, всё в рабочем состоянии, колёса накачаны, амортизация мягкая. В комплекте дождевик, москитная сетка, сумка для мамы и подстаканник. Ткань постирана и обработана, запахов нет. Шасси складывается компактно и помещается в багажник седана. Продаю, потому что ребёнок вырос и коляска больше не нужна.',
     2750000, 'published', '{"category":"kids","condition":"used"}', now() - interval '10 days', now() - interval '10 days'),
    ('a0000000-0000-4000-a000-000000000005', 'd0000000-0000-4000-a000-000000000005', 'Ноутбук ASUS Vivobook 15, Ryzen 5',
     'Ноутбук ASUS Vivobook 15 на Ryzen 5, 16 ГБ оперативной памяти и SSD на 512 ГБ. Использовался для учёбы и офисных задач, тяжёлых игр на нём не было. Экран без битых пикселей и царапин, клавиатура с подсветкой, все клавиши работают. Батарея держит около пяти часов при обычной работе. Установлена чистая система, все драйверы на месте. В комплекте оригинальный блок питания и мягкий чехол.',
     4210000, 'published', '{"category":"electronics","condition":"used"}', now() - interval '8 days', now() - interval '8 days'),
    ('a0000000-0000-4000-a000-000000000006', 'd0000000-0000-4000-a000-000000000006', 'Куртка зимняя мужская, размер L',
     'Тёплая зимняя куртка мужская, размер L, наполнитель синтепух. Носил один сезон, выглядит как новая: манжеты не растянуты, молния и все кнопки исправны, капюшон отстёгивается. Держит мороз до минус двадцати пяти, проверено на практике. Цвет тёмно-синий, подойдёт и под повседневный, и под спортивный стиль. Постирана и готова к носке. Продаю, потому что купил другую модель с мембраной.',
     740000, 'published', '{"category":"clothes","condition":"used"}', now() - interval '6 days', now() - interval '6 days'),
    ('a0000000-0000-4000-a000-000000000007', 'd0000000-0000-4000-a000-000000000007', 'Кофемашина De''Longhi Magnifica',
     'Автоматическая кофемашина De''Longhi Magnifica с встроенной кофемолкой и капучинатором. Работает без сбоев, регулярно чистилась и декальцинировалась, чеки на обслуживание сохранились. Готовит эспрессо, американо и капучино, степень помола настраивается. Поддон и контейнер для отходов промыты. Продаю, потому что на работе поставили похожую и дома вторая не нужна. В комплекте мерная ложка и инструкция.',
     2390000, 'published', '{"category":"appliances","condition":"used"}', now() - interval '5 days', now() - interval '5 days'),
    ('a0000000-0000-4000-a000-000000000008', 'd0000000-0000-4000-a000-000000000008', 'Гитара акустическая Yamaha F310',
     'Акустическая гитара Yamaha F310 — классический вариант для обучения и домашней игры. Гриф ровный, строй держит, ладов не задевает. Комплект струн заменён недавно, звук яркий и громкий. На корпусе есть небольшая потёртость у нижней деки, на звук не влияет, на фото видно. В подарок отдам чехол, каподастр и набор медиаторов. Продаю, потому что перешёл на электрогитару и акустика простаивает.',
     980000, 'published', '{"category":"music","condition":"used"}', now() - interval '4 days', now() - interval '4 days'),
    ('a0000000-0000-4000-a000-000000000009', 'd0000000-0000-4000-a000-000000000009', 'Стол письменный IKEA, белый',
     'Письменный стол IKEA белого цвета, столешница 120 на 60 сантиметров. Использовался как рабочее место для ноутбука, следов от кружек и царапин нет. Металлические ножки регулируются по высоте, стол не шатается. Есть встроенный кабель-канал сзади, провода не путаются. Разбирается за десять минут, всю фурнитуру отдам вместе со столом. Продаю из-за переезда в квартиру меньшей площади, торг возможен.',
     560000, 'published', '{"category":"furniture","condition":"used"}', now() - interval '3 days', now() - interval '3 days'),
    ('a0000000-0000-4000-a000-00000000000a', 'd0000000-0000-4000-a000-00000000000a', 'Робот-пылесос Xiaomi, с влажной уборкой',
     'Робот-пылесос Xiaomi с функцией влажной уборки и лазерной навигацией. Строит карту квартиры, запоминает комнаты и обходит препятствия. Аккумулятор держит полный цикл уборки двухкомнатной квартиры и сам возвращается на базу. Щётки и фильтр заменены на новые перед продажей, контейнер вымыт. Управляется через приложение, можно настроить расписание. Продаю, потому что купил модель со станцией самоочистки.',
     1670000, 'published', '{"category":"appliances","condition":"used"}', now() - interval '2 days', now() - interval '2 days'),
    ('a0000000-0000-4000-a000-00000000000b', 'd0000000-0000-4000-a000-00000000000b', 'Сноуборд Burton с креплениями',
     'Сноуборд Burton длиной 155 сантиметров вместе с креплениями. Катался два сезона на подготовленных склонах, кантами о камни не бился, скользящая поверхность ровная. Перед продажей сделал заточку кантов и парафин, доска готова к сезону. Крепления регулируются под ботинок с 41 по 44 размер. Отдам вместе с чехлом для переноски. Продаю, потому что перешёл на горные лыжи и доска простаивает в кладовке.',
     2140000, 'published', '{"category":"sport","condition":"used"}', now() - interval '1 day', now() - interval '1 day'),
    ('a0000000-0000-4000-a000-00000000000c', 'd0000000-0000-4000-a000-00000000000c', 'Монитор Dell 27", IPS, 75 Гц',
     'Монитор Dell с диагональю 27 дюймов, матрица IPS, частота 75 Гц, разрешение Full HD. Битых пикселей нет, засветов по краям тоже, проверял на однотонном чёрном фоне. Подставка регулируется по высоте и наклону, есть крепление VESA. Разъёмы HDMI и DisplayPort, кабель HDMI в комплекте. Использовался дома для работы с документами и кодом. Продаю, потому что взял ультраширокий и этот освободился.',
     1320000, 'published', '{"category":"electronics","condition":"used"}', now() - interval '20 hours', now() - interval '20 hours'),
    ('a0000000-0000-4000-a000-00000000000d', 'd0000000-0000-4000-a000-000000000001', 'Кресло компьютерное, сетчатая спинка',
     'Компьютерное кресло с сетчатой спинкой и поясничной поддержкой. Спина не потеет даже в жару, подлокотники регулируются по высоте. Газлифт исправен, механизм качания работает, колёсики не скрипят и не оставляют следов на ламинате. Обивка сиденья без пятен и затяжек. Покупалось для домашнего кабинета, использовалось примерно год. Продаю в связи с переходом на работу в офис, кресло дома больше не нужно.',
     870000, 'sold',      '{"category":"furniture","condition":"used"}', now() - interval '22 days', now() - interval '9 days'),
    ('a0000000-0000-4000-a000-00000000000e', 'd0000000-0000-4000-a000-000000000002', 'Смарт-часы Amazfit GTR, чёрные',
     'Смарт-часы Amazfit GTR в чёрном корпусе. Держат заряд до двух недель при обычном использовании с включённым пульсометром. Экран AMOLED, яркий и читаемый на солнце, стекло без сколов. Считают шаги, сон и тренировки, синхронизируются с телефоном по Bluetooth. Ремешок силиконовый, есть запасной кожаный. Продаю, потому что подарили другие часы, а две пары носить смысла нет.',
     640000, 'sold',      '{"category":"electronics","condition":"used"}', now() - interval '17 days', now() - interval '7 days')
ON CONFLICT (id) DO NOTHING;

